import '../../domain/entities/starting_baseline.dart'; import '../../domain/repositories/baseline_repository.dart'; import '../datasources/baseline_remote_data_source.dart';
class BaselineRepositoryImpl implements BaselineRepository { const BaselineRepositoryImpl(this._remote); final BaselineRemoteDataSource _remote; @override Future<StartingBaseline> getForTrainer(String traineeId) async=>(await _remote.trainerView(traineeId)).toEntity(); @override Future<Uri> getPhotoReadUri(String traineeId,String photoId) async{final data=await _remote.photoReadAccess(traineeId,photoId);return Uri.parse(data['url'] as String);} }
